CREATE TABLE "beer_city_prices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "country_code" text NOT NULL, "city_id" text NOT NULL, "city_name" text NOT NULL, "average_price_minor" integer NOT NULL, "currency" text NOT NULL, "serving_ml" integer NOT NULL, "serving_label" text NOT NULL, "metric_definition" text NOT NULL, "source_name" text NOT NULL, "source_url" text NOT NULL, "observed_at" timestamptz NOT NULL, "reviewed_at" timestamptz NOT NULL, "valid_until" timestamptz NOT NULL, "active" boolean NOT NULL DEFAULT true, CONSTRAINT "beer_city_prices_value_check" CHECK ("average_price_minor" > 0 AND "serving_ml" > 0 AND "currency" ~ '^[A-Z]{3}$' AND "valid_until" > "reviewed_at"));
CREATE UNIQUE INDEX "beer_city_prices_country_city_unique" ON "beer_city_prices" ("country_code", "city_id");
CREATE INDEX "beer_city_prices_valid_until_idx" ON "beer_city_prices" ("valid_until");
CREATE TABLE "country_beer_brands" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "country_code" text NOT NULL, "country_name" text NOT NULL, "brand_name" text NOT NULL, "origin_statement" text NOT NULL, "source_name" text NOT NULL, "source_url" text NOT NULL, "reviewed_at" timestamptz NOT NULL, "valid_until" timestamptz NOT NULL, "active" boolean NOT NULL DEFAULT true, CONSTRAINT "country_beer_brands_code_check" CHECK ("country_code" ~ '^[A-Z]{2}$' AND "valid_until" > "reviewed_at"));
CREATE UNIQUE INDEX "country_beer_brands_country_unique" ON "country_beer_brands" ("country_code");
CREATE INDEX "country_beer_brands_valid_until_idx" ON "country_beer_brands" ("valid_until");
